package com.oveduumnakal.goatindicators;

import java.awt.Color;

import net.runelite.client.config.Alpha;
import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.ConfigSection;
import net.runelite.client.config.Range;

/** Settings for the goat pit overlay: what is drawn, in which colors, and how the labels read. */
@ConfigGroup(GoatIndicatorsConfig.GROUP)
public interface GoatIndicatorsConfig extends Config
{
	/** Config group key, shared with the plugin so both agree on where settings are stored. */
	String GROUP = "goatindicators";

	/** What is drawn: the pit color indicators, the spikes prompt, and the telegrab highlight. */
	@ConfigSection(
		name = "Indicators",
		description = "Which indicators are drawn.",
		position = 0
	)
	String indicatorsSection = "indicators";

	/** Colors of the pit outline gradient, the reminder fills, and the telegrab highlight. */
	@ConfigSection(
		name = "Indicator Colors",
		description = "Colors of the outline, the reminder fills, and the telegrab highlight.",
		position = 1
	)
	String colorsSection = "colors";

	/** The on-pit text labels and their colors. */
	@ConfigSection(
		name = "Labels",
		description = "The on-pit text labels and their colors.",
		position = 2
	)
	String labelsSection = "labels";

	/** Right-click menu reordering: the Cancel, Walk here, and Clear swaps. */
	@ConfigSection(
		name = "Context Menu",
		description = "Right-click menu reordering to guard against stray left-clicks.",
		position = 3
	)
	String contextMenuSection = "contextMenu";

	/** Everything else. */
	@ConfigSection(
		name = "Misc",
		description = "Everything else.",
		position = 4
	)
	String miscSection = "misc";

	@ConfigItem(
		keyName = "showOverlay",
		name = "Show Color Indicators",
		description = "Draw the colored outline and fills over the goat pit in the scene. The text labels (goat "
			+ "count, total caught, in transit) have their own toggles and still show with this off.",
		section = indicatorsSection,
		position = 1
	)
	default boolean showOverlay()
	{
		return true;
	}

	@ConfigItem(
		keyName = "showAddSpikes",
		name = "Show \"Add Spikes\"",
		description = "Label an empty, unspiked pit so it is obvious it needs spikes before it will catch anything.",
		section = indicatorsSection,
		position = 2
	)
	default boolean showAddSpikes()
	{
		return true;
	}

	@ConfigItem(
		keyName = "highlightTelegrab",
		name = "Highlight Telegrabbable",
		description = "Outline goats you can telegrab into a spiked, non-full pit from where "
			+ "you stand, when you can cast Telekinetic Grab.",
		section = indicatorsSection,
		position = 3
	)
	default boolean highlightTelegrab()
	{
		return true;
	}

	@ConfigItem(
		keyName = "highlightProdable",
		name = "Highlight Prodable",
		description = "While a Cattleprod is equipped, outline the goats you can prod into a spiked, non-full "
			+ "pit. Takes over the telegrab outline while a Cattleprod is held; turn off to keep the telegrab "
			+ "highlight instead.",
		section = indicatorsSection,
		position = 4
	)
	default boolean highlightProdable()
	{
		return true;
	}

	@ConfigItem(
		keyName = "prodFromLocation",
		name = "Prodable from Location",
		description = "Only highlight prodable goats you can prod in from where you stand right now, without "
			+ "walking to reposition — those the pit sits directly beyond, in the direction a prod would shove "
			+ "them. Off highlights every goat within prod range of a catching pit regardless of your position.",
		section = indicatorsSection,
		position = 5
	)
	default boolean prodFromLocation()
	{
		return true;
	}

	@ConfigItem(
		keyName = "telegrabGradient",
		name = "Near/Far Gradient",
		description = "Shade each highlighted goat's outline by its distance to the pit: from the closest "
			+ "color (nearest the pit) to the furthest color. Applies to both the telegrab and prod "
			+ "highlights. Off draws every target in its closest color instead.",
		section = indicatorsSection,
		position = 6
	)
	default boolean telegrabGradient()
	{
		return true;
	}

	@ConfigItem(
		keyName = "highlightSpikeSupply",
		name = "Highlight Spike Supply",
		description = "Outline the spike supply object when a pit needs lining and you are carrying no "
			+ "spikes, so the restock point is obvious. Uses the same spike-warning colors as the pit.",
		section = indicatorsSection,
		position = 7
	)
	default boolean highlightSpikeSupply()
	{
		return true;
	}

	@ConfigItem(
		keyName = "emptyOutlineColor",
		name = "Empty Outline",
		description = "Outline color for an empty or unspiked pit, and the low end of the fill gradient. "
